rule Akira_SonicWall_Exploit {
  strings:
    $uri = "/cgi-bin/sonicwall.cgi"
    $hex = { 55 89 E5 83 EC 18 }
  condition:
    $uri or $hex
}

rule Stuxnet_LNK_Exploit {
  strings:
    $magic = { 4C 00 00 00 01 14 02 00 }
    $clsid = "00021401-0000-0000-C000-000000000046"
  condition:
    $magic at 0 and $clsid
}

rule XZ_Backdoor_Payload {
  strings:
    $b1 = { F3 0F 1E FA E8 ?? ?? ?? ?? 48 89 E5 }
    $sig = "_get_cpuid"
  condition:
    all of them
}
